'use strict';
// A local, explainable prototype. No bank requests or remote AI calls are made.
const $ = (q, root=document) => root.querySelector(q);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => Number(n).toLocaleString('zh-CN',{maximumFractionDigits:0});
const yuan = n => '¥'+money(n);
const day = n => {const d=new Date(2026,8,15);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const shortDate = s => s.slice(5).replace('-','.');
const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',orders:'M7 3h10v3H7z M6 5H4v16h16V5h-2 M8 11h8 M8 16h5',production:'M4 5h16 M4 12h16 M4 19h16 M8 3v4 M16 10v4 M11 17v4',capacity:'M4 20V10 M10 20V4 M16 20v-7 M22 20H2',cash:'M3 17l5-5 4 3 8-10 M15 5h5v5 M3 21h18',finance:'M3 9l9-6 9 6z M5 10v9 M10 10v9 M14 10v9 M19 10v9 M3 21h18',templates:'M4 4h7v7H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h7v7h-7z',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 20h4',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M6 18L18 6',menu:'M4 6h16 M4 12h16 M4 18h16',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',alert:'M12 3L2 21h20z M12 9v5 M12 17v1',leaf:'M19 4C7 2 2 10 7 17s16 2 12-13z M6 19L16 9',book:'M12 5C8 2 3 4 3 4v16s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1z M12 5v16',shield:'M12 3l8 3v6c0 6-8 9-8 9s-8-3-8-9V6z M8 12l3 3 5-6'};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const NAV=[['dashboard','经营总览'],['orders','订单中心'],['production','生产排程'],['capacity','产能模拟'],['cash','现金流预测'],['finance','融资辅助'],['templates','工艺知识库']];
const SEED=[
{id:'JR202609001',name:'鹤舞苇乡 · 芦苇画礼盒',customer:'北岸文旅 · 企业定制',craft:'芦苇画',qty:100,price:1200,deposit:40,due:30,material:360,labour:300,other:100,progress:42,status:'生产中',created:'2026-09-15'},
{id:'JR202609002',name:'松鹤延年 · 芦苇画挂屏',customer:'澄观空间 · 艺术采购',craft:'芦苇画',qty:30,price:1800,deposit:50,due:42,material:500,labour:500,other:150,progress:15,status:'待排产',created:'2026-09-15'},
{id:'JR202609003',name:'湿地拾光 · 芦苇画书签',customer:'芦岸书店 · 文创采购',craft:'芦苇画',qty:200,price:120,deposit:60,due:20,material:25,labour:35,other:10,progress:100,status:'待回款',created:'2026-09-15'}];
const PROCESS=[['选材',.10,'原料整理'],['处理',.18,'浸泡与剖平'],['剪裁',.30,'图样剪裁'],['拼贴',.55,'核心手工工序'],['装裱',.25,'成品装裱'],['质检',.08,'质量复核'],['包装',.06,'礼盒包装']];
const STORAGE='jiangrong-workbench-v1';
let state={orders:structuredClone(SEED),active:SEED[0].id,opening:8000,safety:10000,workers:1,scenario:'base',logs:[],completed:[]};
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved&&Array.isArray(saved.orders)&&saved.orders.length&&saved.orders.every(o=>o.id&&Number.isFinite(o.qty)&&o.qty>0&&Number.isFinite(o.price)&&o.price>=0))state={...state,...saved};}catch{}
let view=location.hash.slice(1)||'dashboard', search='', filter='全部', chartMode='balance';
if(!NAV.some(n=>n[0]===view))view='dashboard';
function current(){return state.orders.find(o=>o.id===state.active)||state.orders[0]}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{toast('浏览器未允许保存，请导出数据留存。')}}
function log(text){state.logs.unshift({text,time:new Date().toLocaleString('zh-CN',{hour12:false})});state.logs=state.logs.slice(0,50);save()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function go(v){if(view===v)render();else location.hash=v;document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.mobile-shade')?.classList.remove('visible')}
window.addEventListener('hashchange',()=>{view=location.hash.slice(1);if(!NAV.some(n=>n[0]===view))view='dashboard';search='';filter='全部';render();window.scrollTo(0,0)});
function flow(o=current(),scenario=state.scenario){
 const q=o.qty*(scenario==='reduce'?.8:1), total=q*o.price, pre=total*o.deposit/100, tail=total-pre;
 const materials=q*o.material*(scenario==='material'?1.1:1), labour=q*o.labour, other=q*o.other;
 const incomes=Array(8).fill(0), expenses=Array(8).fill(0), recovery=Math.max(0,Math.min(7,Math.ceil(o.due/7)-1+(scenario==='delay'?2:0)));
 incomes[0]=pre;incomes[recovery]+=tail;
 for(let i=0;i<4;i++)expenses[i]=labour/4;
 expenses[1]+=materials;expenses[3]+=other;
 if(scenario==='spread'){expenses[1]-=materials*.5;expenses[3]+=materials*.5;}
 let balance=state.opening;
 const rows=incomes.map((income,i)=>{const start=balance;balance+=income-expenses[i];return {week:i+1,start,income,expense:expenses[i],balance}});
 const min=Math.min(...rows.map(r=>r.balance)), gap=Math.max(0,state.safety-min), first=rows.findIndex(r=>r.balance<state.safety);
 return{rows,total,pre,tail,materials,labour,other,min,gap,first:first+1,recovery:recovery+1,profit:total-materials-labour-other};
}
function schedule(o=current(),workers=state.workers){let start=0;return PROCESS.map(([name,hint,detail],i)=>{const count=i===3?workers:1;const hours=Math.round(o.qty*hint*10)/10;const days=Math.max(1,Math.ceil(hours/(count*6)));const item={name,detail,hours,count,days,start,end:start+days,index:i};start+=days;return item})}
function orderSelect(){return `<select class="input" id="active-order" aria-label="选择分析订单" style="max-width:310px">${state.orders.map(o=>`<option value="${esc(o.id)}" ${current().id===o.id?'selected':''}>${esc(o.name)} · ${o.qty}件</option>`).join('')}</select>`}
function header(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">JIANGRONG / ${view.toUpperCase()}</div><h1>${title}</h1><p class="subheading">${sub}</p></div><div class="row">${actions}</div></div>`}
function panel(title,sub,body,action='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div><div class="panel-body">${body}</div></section>`}
function metric(label,value,unit,foot,ico,accent=''){return `<div class="metric"><div class="metric-top"><span>${label}</span>${icon(ico)}</div><div class="number ${accent}">${value}${unit?`<span>${unit}</span>`:''}</div><div class="metric-foot">${foot}</div></div>`}
function chart(rows,mode='balance'){
 const values=rows.map(r=>mode==='balance'?r.balance:r.income-r.expense), all=[...values,0,state.safety],max=Math.max(...all)*1.17||1,min=Math.min(...all)<0?Math.min(...all)*1.5:0;
 const X=i=>48+i*530/(rows.length-1), Y=v=>170-(v-min)/(max-min)*143;
 const points=values.map((v,i)=>`${X(i)},${Y(v)}`).join(' '), zero=Y(0),safe=Y(state.safety);
 return `<svg class="chart" viewBox="0 0 610 218" role="img" aria-label="${rows.length}周${mode==='balance'?'期末现金余额':'每周净现金流'}，${values.map((v,i)=>`第${i+1}周${money(v)}元`).join('，')}"><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#57896a" stop-opacity=".18"/><stop offset="100%" stop-color="#57896a" stop-opacity=".01"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=min+(max-min)*i/3;return `<line x1="48" y1="${Y(v)}" x2="580" y2="${Y(v)}" stroke="#eef1eb" stroke-dasharray="3 5"/><text x="37" y="${Y(v)+4}" text-anchor="end">${(v/10000).toFixed(1)}万</text>`}).join('')}${mode==='balance'?`<line x1="48" y1="${safe}" x2="580" y2="${safe}" stroke="#c8ae79" stroke-dasharray="5 5"/>`:''}<polygon points="48,${zero} ${points} 578,${zero}" fill="url(#areaFill)"/><polyline points="${points}" fill="none" stroke="#356b50" stroke-width="2.6" stroke-linejoin="round"/>${values.map((v,i)=>`<g><circle cx="${X(i)}" cy="${Y(v)}" r="4" fill="white" stroke="${v<state.safety?'#bd9f67':'#356b50'}" stroke-width="2"/><text x="${X(i)}" y="${Y(v)-13}" text-anchor="middle" style="fill:#59725b">${(v/10000).toFixed(2)}万</text><text x="${X(i)}" y="196" text-anchor="middle">第${i+1}周</text><title>第${i+1}周：${money(v)}元</title></g>`).join('')}</svg>`;
}
function cashPanel(compact=true){const f=flow();return `<section class="panel chart-panel"><div class="panel-head"><div><h2>未来${compact?'4':'8'}周现金流</h2><p>${esc(current().name)} · 单笔订单测算</p></div><div class="segmented" aria-label="图表类型"><button data-chart="balance" class="${chartMode==='balance'?'active':''}">余额</button><button data-chart="net" class="${chartMode==='net'?'active':''}">净流入</button></div></div><div class="panel-body"><div class="legend"><span><i></i>${chartMode==='balance'?'期末现金余额':'每周净现金流'}</span>${chartMode==='balance'?'<span><i class="gold"></i>安全阈值</span>':''}<span style="margin-left:auto">单位：元</span></div>${chart(f.rows.slice(0,compact?4:8),chartMode)}</div><div class="chart-summary"><span>${f.gap>0?`第 ${f.first} 周起低于安全阈值，最大资金补足需求 <strong>${yuan(f.gap)}</strong>`:'预测期内现金余额高于安全阈值'}</span><button class="text-link" data-go="cash">查看测算 ${icon('arrow')}</button></div></section>`}
function capacityPanel(){const s=schedule(),o=current();return panel('关键工序负荷','按分配窗口与每日 6 小时估算',`${[2,3,4].map((idx,j)=>{const p=s[idx],window=[6,8,5][j],ratio=Math.round(p.hours/(p.count*6*window)*100);return `<div class="capacity-row"><div class="capacity-title"><span>${p.name}<small class="muted"> / ${p.count}人 · ${window}天窗口</small></span><span class="number ${ratio>100?'warning':''}">${ratio}%</span></div><div class="track"><i style="width:${Math.min(100,ratio)}%;${ratio>100?'background:#bba06c':''}"></i></div></div>`}).join('')}<div class="capacity-note">${o.qty*.55/(state.workers*48)>1?'拼贴超出分配窗口，可在产能模拟中增加熟练人员。':'关键拼贴工序处于可承接范围。'} 总工期 ${s.at(-1).end} 天。</div>`,`<button class="text-link" data-go="capacity">模拟 ${icon('arrow')}</button>`)}
function orderTable(orders,full=false){return `<div class="table-wrap"><table><thead><tr><th>订单 / 客户</th><th>订单金额</th><th>交付日期</th><th>生产进度</th><th>状态</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><div class="order-name"><span class="order-thumb">苇</span><div><b>${esc(o.name)}</b><small>${esc(o.customer)} · ${o.qty}件</small></div></div></td><td class="number">${yuan(o.qty*o.price)}</td><td class="number">${shortDate(day(o.due))}</td><td><div class="table-progress"><div class="track"><i style="width:${o.progress}%"></i></div><small class="mono">${o.progress}%</small></div></td><td><span class="pill ${o.status==='待回款'?'amber':o.status==='待排产'?'gray':''}">${esc(o.status)}</span></td><td><button class="text-link" data-detail="${esc(o.id)}">详情 ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">没有匹配的订单，请调整搜索条件。</td></tr>'}</tbody></table></div>`}
function risks(){const f=flow(),s=schedule();const items=[];if(f.gap>0)items.push(['cash','资金周转提醒',`第${f.first}周起低于安全阈值，最大需补足 ${yuan(f.gap)}。`,'查看资金计划']);if(s.at(-1).end>current().due)items.push(['capacity','交付时间预警',`计划需 ${s.at(-1).end} 天，超过交期 ${s.at(-1).end-current().due} 天。`,'调整人员配置']);else items.push(['capacity','关键工序关注',`拼贴需 ${s[3].hours} 工时，可模拟增加熟练人员。`,'查看产能方案']);const awaiting=state.orders.filter(o=>o.status==='待回款');if(awaiting.length)items.push(['orders','待回款订单',`${awaiting.length} 笔订单等待回款确认，请核实付款节点。`,'查看订单']);return items.map(([v,title,body,link])=>`<div class="risk-item"><span class="risk-icon">${icon(v==='cash'?'cash':v==='capacity'?'clock':'orders')}</span><div><h3>${title}</h3><p>${body}</p><button class="text-link" data-go="${v}">${link} ${icon('arrow')}</button></div></div>`).join('')}
function dashboard(){const f=flow(),s=schedule(),total=state.orders.reduce((a,o)=>a+o.qty*o.price,0),pending=state.orders.filter(o=>o.progress<100).length,receivable=state.orders.filter(o=>o.status!=='已完成').reduce((a,o)=>a+o.qty*o.price*(1-o.deposit/100),0);return header('把手艺，经营得更从容','从一笔真实订单出发，看清生产与资金的每一步。',`<button class="btn" data-action="export">${icon('download')}经营简报</button><button class="btn primary" data-action="new">${icon('plus')}新建订单</button>`)+`<section class="hero"><div><div class="eyebrow">CRAFT WITH PURPOSE. GROW WITH CONFIDENCE.</div><h2>手有匠心，经营有数。</h2><p>订单、工序与现金流，在这里连成清晰的经营脉络。<br>今天，先关注 ${esc(current().name.split(' · ')[0])} 的交付计划。</p><div class="row"><button class="btn gold" data-go="production">查看生产计划 ${icon('arrow')}</button><button class="text-link" data-detail="${esc(current().id)}">打开订单档案 ${icon('arrow')}</button></div></div><div class="hero-right"><div class="hero-mini"><small style="color:#b8ccbd">当前订单预计工期</small><div class="number">${s.at(-1).end}<span style="font-size:14px;color:#b8ccbd"> 天</span></div><span class="muted" style="font-size:12px">${s.at(-1).end<=current().due?`距约定交期有 ${current().due-s.at(-1).end} 天余量`:`超过约定交期 ${s.at(-1).end-current().due} 天`}</span></div><div class="ring" style="background:conic-gradient(#cdb582 0 ${current().progress}%,#ffffff15 ${current().progress}%)"><div class="ring-inner"><span class="number">${current().progress}<small>%</small></span><small>订单完成度</small></div></div></div></section><div class="metrics">${metric('本月订单总额',money(total),'元','<span class="positive">订单全量汇总</span>','orders')}${metric('待交付订单',pending,'笔','<span>持续跟踪生产节点</span>','production')}${metric('预计待收尾款',money(receivable),'元','<span>按合同付款比例计算</span>','cash')}${metric('当前订单资金补足',money(f.gap),'元',`<span class="warning">${f.gap?'安全阈值 '+yuan(state.safety):'预测期资金充足'}</span>`,'finance',f.gap?'warning':'')}</div><div class="grid-main">${cashPanel()}${capacityPanel()}</div><div class="grid-main"><section class="panel"><div class="panel-head" style="padding-bottom:20px"><div><h2>订单进行时</h2><p>让每一份手作，都如期抵达</p></div><button class="text-link" data-go="orders">全部订单 ${icon('arrow')}</button></div>${orderTable(state.orders.slice(0,3))}</section>${panel('经营提醒','值得留意的下一步',risks(),'<span class="pill amber">动态测算</span>')}</div>`}
function ordersPage(){let list=state.orders.filter(o=>(filter==='全部'||o.status===filter)&&(o.name+o.customer+o.id).toLowerCase().includes(search.toLowerCase()));return header('订单中心','一单一档，连接接单、生产、交付与回款。',`<button class="btn" data-action="exportOrders">${icon('download')}导出</button><button class="btn primary" data-action="new">${icon('plus')}新建订单</button>`)+`<div class="panel"><div class="filters"><div class="scenario-options" style="margin:0">${['全部','待排产','生产中','待回款','已完成'].map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div><input class="input search" id="search" placeholder="搜索订单、客户或编号" aria-label="搜索订单" value="${esc(search)}"></div>${orderTable(list,true)}</div><div class="notice">演示数据保存在当前浏览器。新增订单会参与订单总额与尾款汇总；生产和现金流按当前选中订单分别测算。</div>`}
function productionPage(){const o=current(),s=schedule(),end=s.at(-1).end;return header('生产排程','从一张订单，拆解到每一道工序。',orderSelect())+`<div class="flow">${['订单确认','工序拆解','执行生产','质检交付','尾款回收'].map((t,i)=>`<div class="flow-item ${i<3?'active':''}"><small>0${i+1}</small><b>${t}</b></div>`).join('')}</div><div class="metrics">${metric('生产需求',o.qty,'件',esc(o.craft),'orders')}${metric('累计工时',money(s.reduce((a,p)=>a+p.hours,0)),'小时','每人每日有效工时 6 小时','clock')}${metric('预计生产周期',end,'天','工序顺序执行，向上取整','production')}${metric('交付余量',o.due-end,'天',end>o.due?'需调整人员或交期':'约定 '+o.due+' 天交付','capacity',end>o.due?'danger':'')}</div><div class="grid-main">${panel('工序时间轴','报告芦苇画模板 · 从第 1 天起顺序排程',`<div class="table-wrap"><div class="gantt"><div class="gantt-row muted" style="font-size:12px"><span>工序</span><div style="display:flex;justify-content:space-between"><span>第 1 天</span><span>第 ${Math.ceil(end/2)} 天</span><span>第 ${end} 天</span></div><span>工时</span></div>${s.map(p=>`<div class="gantt-row"><span>${p.name}</span><div class="gantt-track"><div class="gantt-bar ${p.index===3?'key':''}" style="left:${p.start/end*100}%;width:${p.days/end*100}%" title="${p.name}：第${p.start+1}至${p.end}天">${p.days}天</div></div><span class="mono muted">${p.hours} h</span></div>`).join('')}</div></div><div class="notice">顺序工序模型：工期 = 各工序向上取整（数量 × 单件工时 ÷ 人数 ÷ 6 小时）之和；未计入节假日、返工及其他订单占用。</div>`,`<button class="text-link" data-go="capacity">调整方案 ${icon('arrow')}</button>`)}${panel('工序执行记录','完成状态仅作用于当前订单',s.map(p=>{const checked=state.completed.includes(o.id+':'+p.index);return `<label class="check-row" style="cursor:pointer"><input type="checkbox" data-process="${p.index}" ${checked?'checked':''} style="accent-color:var(--green)"><div><h3>${p.name}</h3><small class="muted">${p.detail} · ${p.count}人</small></div><span>${checked?'已完成':'待完成'}</span></label>`}).join('')+'<p class="muted" style="font-size:12px;margin-top:15px">勾选工序会按完成工时占比更新订单进度。首次登记将替代演示进度。</p>')}</div>`}
function capacityPage(){const o=current(),base=schedule(o,1),s=schedule(),days=s.at(-1).end,baseDays=base.at(-1).end;return header('产能模拟','先判断能不能做，再安排如何如期交付。',orderSelect())+`<div class="two">${panel('人员与交期','调整拼贴工序人数，对比交付变化',`<div class="slider-block"><label for="workers"><span>拼贴熟练人员</span><strong class="number">${state.workers} 人</strong></label><input id="workers" type="range" min="1" max="5" step="1" value="${state.workers}"><div class="row muted" style="justify-content:space-between;font-size:12px"><span>1 人</span><span>5 人</span></div></div><div class="detail-grid" style="grid-template-columns:1fr 1fr"><div><dt>订单数量</dt><dd>${o.qty} 件</dd></div><div><dt>约定交期</dt><dd>${o.due} 天</dd></div><div><dt>单件拼贴工时</dt><dd>0.55 小时</dd></div><div><dt>每日有效工时</dt><dd>6 小时 / 人</dd></div></div><div class="notice">演示假设：新增人员熟练度相同、可以并行作业。此处只比较工期，新增人工成本需在订单成本中单独调整。</div><button class="btn primary" data-action="applyPlan">${icon('check')}保存当前排程方案</button>`)}${panel('方案对比','规则测算，结果随人数实时更新',`<div class="two"><div class="stat-box"><span class="muted">基准方案 · 1人拼贴</span><div class="number">${baseDays} <small>天</small></div></div><div class="stat-box" style="background:#eaf1e8"><span class="muted">当前方案 · ${state.workers}人拼贴</span><div class="number">${days} <small>天</small></div></div></div><div style="padding:27px 0"><h2>${days<=o.due?'当前配置可在约定时间内完成':'当前配置仍有延期风险'}</h2><p class="subheading">相较基准缩短 ${baseDays-days} 天，${days<=o.due?'交付余量 '+(o.due-days)+' 天':'预计延期 '+(days-o.due)+' 天'}。</p></div>${s.filter(p=>[2,3,4].includes(p.index)).map(p=>`<div class="capacity-row"><div class="capacity-title"><span>${p.name}</span><span>${p.days} 天 · ${p.count} 人</span></div><div class="track"><i style="width:${p.days/days*100}%;${p.index===3?'background:#bda371':''}"></i></div></div>`).join('')}<button class="text-link" data-go="production">查看完整工序时间轴 ${icon('arrow')}</button>`)}</div>`}
const SCENARIOS=[['base','基准方案'],['material','材料涨价 10%'],['delay','尾款延后 2 周'],['reduce','订单数量减少 20%'],['spread','采购分两批支付']];
function cashPage(){const f=flow(),o=current();return header('现金流预测','看清缺口的时间、原因，以及预计回款来源。',`<button class="btn" data-action="exportCash">${icon('download')}导出测算表</button>`)+`<div class="row wrap" style="justify-content:space-between;margin-bottom:18px">${orderSelect()}<div class="row"><label for="opening" class="muted">期初现金</label><input class="input" id="opening" type="number" min="0" max="100000000" value="${state.opening}" style="width:120px"><label for="safety" class="muted">安全阈值</label><input class="input" id="safety" type="number" min="0" max="100000000" value="${state.safety}" style="width:120px"></div></div><div class="scenario-options" aria-label="压力测试情景">${SCENARIOS.map(([k,t])=>`<button data-scenario="${k}" class="${state.scenario===k?'active':''}">${t}</button>`).join('')}</div><div class="metrics">${metric('最低现金余额',money(f.min),'元','预测未来 8 周','cash',f.min<0?'danger':'')}${metric('负余额缺口',money(Math.max(0,-f.min)),'元','补至 0 元所需金额','finance')}${metric('安全阈值补足',money(f.gap),'元','补至 '+yuan(state.safety)+' 所需金额','shield',f.gap?'warning':'')}${metric('预计尾款回收','第 '+f.recovery,'周','尾款 '+yuan(f.tail),'orders')}</div><div class="grid-main">${cashPanel(false)}${panel('资金缺口解释','可追溯到订单付款与生产支出',`<div class="risk-item"><span class="risk-icon">${icon('orders')}</span><div><h3>第 2 周 · 材料集中采购</h3><p>材料总成本 ${yuan(f.materials)}${state.scenario==='spread'?'，第 2、4 周各支付 50%':'，在第 2 周支付'}。</p></div></div><div class="risk-item"><span class="risk-icon">${icon('production')}</span><div><h3>前 4 周 · 连续人工支出</h3><p>人工总成本 ${yuan(f.labour)}，分 4 周等额支付。</p></div></div><div class="risk-item"><span class="risk-icon">${icon('cash')}</span><div><h3>第 ${f.recovery} 周 · 尾款到账</h3><p>交付后预计回收 ${yuan(f.tail)}；预付款在第 1 周收到。</p></div></div><button class="btn primary" style="width:100%;margin-top:20px" data-go="finance">整理融资辅助材料 ${icon('arrow')}</button>`)}</div><section class="panel"><div class="panel-head" style="padding-bottom:18px"><h2>逐周现金流明细</h2><span class="muted" style="font-size:12px">期末余额 = 期初 + 流入 − 流出</span></div><div class="table-wrap"><table><thead><tr><th>预测周期</th><th>期初现金</th><th>预计流入</th><th>预计流出</th><th>期末现金</th><th>安全阈值差额</th></tr></thead><tbody>${f.rows.map(r=>`<tr><td>第 ${r.week} 周</td><td class="number">${yuan(r.start)}</td><td class="number positive">${yuan(r.income)}</td><td class="number">${yuan(r.expense)}</td><td class="number ${r.balance<0?'danger':''}">${yuan(r.balance)}</td><td class="number ${r.balance<state.safety?'warning':'muted'}">${r.balance<state.safety?yuan(state.safety-r.balance):'—'}</td></tr>`).join('')}</tbody></table></div></section><div class="notice">测算假设：订单在演示基准日 2026-09-15 接单，预付款在第 1 周、材料在第 2 周、人工在前 4 周、其他费用在第 4 周发生，尾款按交付天数对应周回收。压力测试为独立情景，不改写订单；未纳入税费、融资利息及其他订单资金占用。</div>`}
function financePage(){const o=current(),f=flow(),s=schedule();return header('融资辅助','把经营过程，整理成可解释、可复核的材料。',orderSelect())+`<section class="finance-cover"><div class="eyebrow" style="color:#b5c8b5">BUSINESS EVIDENCE / FINANCING SUPPORT</div><h2>让每一笔资金需求，都有据可循。</h2><p>以订单为起点，以生产计划为依据，以预计回款为参考。<br>整理完整经营信息，供客户与银行进一步沟通。</p></section><div class="notice">当前为项目演示，未接入工商银行系统。平台仅提供经营测算和材料整理，不提供授信结论，也不会提交真实融资申请。</div><div class="two">${panel('经营信息摘要',SCENARIOS.find(x=>x[0]===state.scenario)?.[1]+' · 当前测算情景',`<dl class="detail-grid" style="grid-template-columns:1fr 1fr"><div><dt>订单原始金额</dt><dd class="number">${yuan(o.qty*o.price)}</dd></div><div><dt>情景测算金额</dt><dd class="number">${yuan(f.total)}</dd></div><div><dt>安全阈值补足需求</dt><dd class="number warning">${yuan(f.gap)}</dd></div><div><dt>预计回款来源</dt><dd>订单尾款 ${yuan(f.tail)}</dd></div><div><dt>原订单计划工期</dt><dd>${s.at(-1).end} 天</dd></div><div><dt>预计回款时间</dt><dd>第 ${f.recovery} 周</dd></div></dl><p class="muted">资金用途：材料采购、工序人工和包装物流。<br>金额来源：当前选中订单及当前压力测试情景。</p>`)}${panel('材料完整性清单','自动汇总已录入信息，原始凭证需另行准备',`<div class="check-row">${icon('check')}订单基本信息<span>已录入</span></div><div class="check-row">${icon('check')}生产工序与工时计划<span>规则测算</span></div><div class="check-row">${icon('check')}成本与逐周现金流<span>已生成</span></div><div class="check-row">${icon('alert')}原始合同与结算凭证<span class="warning">待线下核实</span></div><label class="checkbox"><input id="confirm-export" type="checkbox"><span>我已了解以上为演示测算，愿意导出当前经营辅助材料供人工核对。</span></label><button class="btn primary" id="finance-export" data-action="financeExport" disabled>${icon('download')}导出经营辅助材料</button>`)}</div><div style="margin-top:22px">${panel('操作记录','仅记录当前浏览器内的新增、更新与导出操作',state.logs.slice(0,6).map(l=>`<div class="audit-item"><time>${esc(l.time)}</time><span>${esc(l.text)}</span></div>`).join('')||'<div class="empty" style="padding:25px">暂无操作记录，完成订单录入或导出后将在此留痕。</div>')}</div>`}
function templatesPage(){return header('工艺知识库','让经验有迹可循，让每一道手艺都有自己的标准。')+`<div class="three"><article class="template-card"><div class="template-symbol">苇</div><span class="pill">首期验证模板</span><h2 style="margin-top:12px">芦苇画</h2><p>以芦苇为墨，连接选材、处理、剪裁、拼贴与装裱等七道工序。</p><div class="row muted" style="font-size:12px;margin-bottom:22px"><span>7 道工序</span><span>人工确认</span><span>规则模型</span></div><button class="btn primary" data-action="template">查看工序模板 ${icon('arrow')}</button></article><article class="template-card"><div class="template-symbol">绣</div><span class="pill gray">拓展规划</span><h2 style="margin-top:12px">传统刺绣</h2><p>待试点采集针法、绣面密度与工时信息，建立可验证的生产模板。</p><span class="muted">尚无已验证工时，不参与测算</span></article><article class="template-card"><div class="template-symbol">陶</div><span class="pill gray">拓展规划</span><h2 style="margin-top:12px">陶艺制作</h2><p>待试点采集成型、干燥与烧制约束，建立材料和设备协同规则。</p><span class="muted">尚无已验证工时，不参与测算</span></article></div><div style="margin-top:23px">${panel('模板使用原则','源自报告提出的“行业模板 + 规则模型 + 人工确认”',`<div class="three"><div><h3>01 · 工序可追溯</h3><p class="subheading">每项工时都回到具体工序，支持手艺人核对生产假设。</p></div><div><h3>02 · 约束先于预测</h3><p class="subheading">先保证工序先后关系与人员可用时间，再判断交付余量。</p></div><div><h3>03 · 试点持续校准</h3><p class="subheading">演示工时不代表行业标准，应以真实生产记录逐步修正。</p></div></div>`)}</div>`}
function render(){const title=NAV.find(n=>n[0]===view)?.[1]||'经营总览';$('#app').innerHTML=`<div class="mobile-shade" data-action="closeNav"></div><aside class="sidebar"><div class="brand"><span class="brandmark">匠</span><div><b>匠融未来</b><small>CRAFT & CAPITAL</small></div></div><div class="workspace"><span class="avatar">苇</span><div><b style="font-weight:500">芦岸非遗工作室</b><small class="muted" style="display:block">经营者工作台</small></div></div><div class="section-label">WORKSPACE / 经营管理</div><nav class="nav" aria-label="主导航">${NAV.map(([id,t])=>`<button data-go="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(id)}<span>${t}</span>${id==='finance'?'<span class="badge">辅助</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="heritage-note"><p>守住手艺 · 看见未来</p><small class="muted">非遗数字经营，让传承生生不息。</small></div><div class="profile"><span class="avatar">芦</span><div><b style="font-weight:500;font-size:13px">工作室管理员</b><small class="muted" style="display:block">本地演示空间</small></div><button class="text-link" data-action="about" aria-label="了解演示空间">${icon('shield')}</button></div></div></aside><div class="shell"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" data-action="menu" aria-label="打开导航">${icon('menu')}</button><span class="crumb">工作台 <span style="padding:0 12px;color:#b6beb2">/</span> <b>${title}</b></span></div><div class="top-actions"><span class="date muted" style="font-size:12px">演示基准日 · 2026.09.15</span><span class="demo-tag">演示数据</span><button class="icon-button notification" data-action="notifications" aria-label="经营提醒">${icon('bell')}</button></div></header><main class="main" id="main" tabindex="-1">${({dashboard,orders:ordersPage,production:productionPage,capacity:capacityPage,cash:cashPage,finance:financePage,templates:templatesPage}[view])()}<footer class="footer" style="margin-top:24px"><span>匠融未来 · 让传统技艺走向可持续经营</span><span>规则测算 / 本地保存 / 未接入银行与 OCR 服务</span></footer></main></div>`;bind()}
function modal(title,body,foot=''){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());if(!d.open)d.showModal();d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}}
function detail(id){const o=state.orders.find(x=>x.id===id);if(!o)return;modal('订单档案',`<span class="pill">${esc(o.status)}</span><h2 style="font-size:23px;margin-top:12px">${esc(o.name)}</h2><p class="subheading">${esc(o.customer)} · ${esc(o.id)}</p><dl class="detail-grid" style="grid-template-columns:1fr 1fr"><div><dt>订单数量</dt><dd>${o.qty} 件</dd></div><div><dt>订单金额</dt><dd>${yuan(o.qty*o.price)}</dd></div><div><dt>预付款比例</dt><dd>${o.deposit}%</dd></div><div><dt>预计交付日期</dt><dd>${day(o.due)}</dd></div><div><dt>单件材料成本</dt><dd>${yuan(o.material)}</dd></div><div><dt>单件人工成本</dt><dd>${yuan(o.labour)}</dd></div><div><dt>单件其他成本</dt><dd>${yuan(o.other)}</dd></div><div><dt>生产进度</dt><dd>${o.progress}%</dd></div></dl><p class="muted">工艺类型：${esc(o.craft)}。数据为人工录入或演示假设，需与原始订单核对。</p>`,`<button class="btn" id="edit-order">编辑信息</button>${o.status==='待回款'?'<button class="btn" id="mark-paid">确认已回款</button>':''}<button class="btn primary" id="analyze-order">查看生产与资金</button>`);$('#edit-order').onclick=()=>orderForm(o);$('#analyze-order').onclick=()=>{state.active=o.id;save();$('#modal').close();go('production')};if($('#mark-paid'))$('#mark-paid').onclick=()=>{o.status='已完成';o.progress=100;log('人工确认订单 '+o.id+' 已回款');$('#modal').close();render();toast('已记录回款确认')}}
function orderForm(existing){const o=existing||{name:'',customer:'',qty:100,price:1200,deposit:40,due:30,material:360,labour:300,other:100};modal(existing?'编辑订单':'新建非遗订单',`<form id="order-form"><div class="field" style="margin-bottom:18px"><label for="order-text">粘贴订单文本（可选）</label><textarea id="order-text" placeholder="例如：100件芦苇画，单价1200元，30天交付，预付款40%"></textarea><div class="row" style="justify-content:space-between"><small class="muted">规则提取演示，非 OCR 或大模型识别。提取后请核对。</small><button type="button" class="btn small" id="parse-text">提取字段</button></div><small id="parse-result" role="status" class="warning"></small></div><div class="form-grid">${[['name','订单名称','text',o.name],['customer','客户名称','text',o.customer],['qty','订单数量 / 件','number',o.qty],['price','单价 / 元','number',o.price],['deposit','预付款 / %','number',o.deposit],['due','交付周期 / 天','number',o.due],['material','单件材料成本 / 元','number',o.material],['labour','单件人工成本 / 元','number',o.labour],['other','单件其他成本 / 元','number',o.other]].map(([key,label,type,value])=>`<div class="field"><label for="f-${key}">${label}</label><input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" required ${type==='number'?`min="${key==='qty'||key==='due'?1:0}" max="${key==='deposit'?100:key==='due'?42:1000000}" step="${['qty','due'].includes(key)?1:.01}"`:'maxlength="80"'}></div>`).join('')}<div class="field"><label>工艺模板</label><input value="芦苇画 · 首期验证模板" disabled></div></div><div class="notice">新订单默认成本仅为演示值，请按实际情况修改。当前现金流模型支持 1–42 天交期，预留 2 周尾款延期模拟。</div></form>`,`<button class="btn" data-close>取消</button><button class="btn primary" id="save-order">确认并保存订单</button>`);
 $('#parse-text').onclick=()=>{const t=$('#order-text').value;const patterns={qty:/(\d+)\s*件/,price:/单价\s*[¥￥]?\s*(\d+(?:\.\d+)?)/,due:/(\d+)\s*天/,deposit:/(?:预付(?:款)?|首付)\s*(\d+(?:\.\d+)?)\s*%/};let hits=[];for(const [k,re]of Object.entries(patterns)){const m=t.match(re);if(m){$('#f-'+k).value=m[1];hits.push({qty:'数量',price:'单价',due:'交期',deposit:'预付款'}[k])}}$('#parse-result').textContent=hits.length?'已提取：'+hits.join('、')+'。其余字段保留原值，请逐项核对。':'未识别到明确字段，请手动填写。'};
 $('#save-order').onclick=()=>{const form=$('#order-form');if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));data.name=data.name.trim();data.customer=data.customer.trim();if(!data.name||!data.customer){toast('请填写订单名称和客户名称');return}for(const k of ['qty','price','deposit','due','material','labour','other'])data[k]=Number(data[k]);let record;if(existing){Object.assign(existing,data);record=existing}else{record={...data,id:'JR'+Date.now(),craft:'芦苇画',progress:0,status:'待排产',created:'2026-09-15'};state.orders.unshift(record)}state.active=record.id;log((existing?'更新':'新增')+'订单 '+record.id);$('#modal').close();go('orders');toast('订单已保存，可进入详情查看排产与现金流')};
}
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob(['\ufeff',content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csv(rows){return rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@\t\r]/.test(s)||(/^\-/.test(s)&&!/^\-\d+(\.\d+)?$/.test(s)))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(',')).join('\r\n')}
function exportReport(finance=false){const o=current(),f=flow(),s=schedule();const text=`匠融未来 · ${finance?'融资辅助材料':'经营简报'}\n生成时间：${new Date().toLocaleString('zh-CN')}\n演示基准日：2026-09-15\n\n【重要说明】\n本材料为本地演示测算，不是银行授信决定；未提交任何申请。需以真实合同、成本与回款凭证核验。\n\n【订单信息】\n订单编号：${o.id}\n订单名称：${o.name}\n客户：${o.customer}\n数量：${o.qty}件\n单价：${o.price}元\n原始总额：${o.qty*o.price}元\n预付款：${o.deposit}%\n约定交期：${o.due}天\n\n【生产能力】\n${s.map(p=>`${p.name}：${p.hours}工时，${p.count}人，第${p.start+1}至${p.end}天`).join('\n')}\n预计总工期：${s.at(-1).end}天\n生产为原订单数量，未应用现金流压力情景的减量。\n\n【现金流测算】\n情景：${SCENARIOS.find(x=>x[0]===state.scenario)[1]}\n期初现金：${state.opening}元\n安全阈值：${state.safety}元\n最低现金余额：${f.min}元\n负余额缺口：${Math.max(0,-f.min)}元\n安全阈值补足：${f.gap}元\n预计尾款：${f.tail}元，第${f.recovery}周回收\n材料成本：${f.materials}元\n人工成本：${f.labour}元\n其他成本：${f.other}元\n\n周期,期初,流入,流出,期末\n${f.rows.map(r=>[r.week,r.start,r.income,r.expense,r.balance].join(',')).join('\n')}\n\n【模型假设】\n顺序工序排程，每人每天6小时，工序天数向上取整。现金流预付款第1周，材料第2周，人工前4周均摊，其他费用第4周，尾款按交期所属周收回。采购分批情景为第2、4周各付50%。未计税费、利息、返工、节假日及其他订单占用。\n\n【待人工核实】\n原始合同、客户付款承诺、材料报价、工资与物流凭证、经营主体资质。\n`;
 download(`${o.id}-${finance?'融资辅助材料':'经营简报'}.txt`,text);log('导出 '+o.id+' '+(finance?'融资辅助材料':'经营简报'));toast('材料已导出至浏览器下载目录');if(finance)render()}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{chartMode=b.dataset.chart;render()});document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{state.scenario=b.dataset.scenario;save();render()});
 if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};
 if($('#active-order'))$('#active-order').onchange=e=>{state.active=e.target.value;save();render()};
 if($('#workers'))$('#workers').oninput=e=>{state.workers=Number(e.target.value);const scroll=window.scrollY;render();$('#workers').focus();window.scrollTo(0,scroll)};
 for(const k of ['opening','safety'])if($('#'+k))$('#'+k).onchange=e=>{if(!e.target.checkValidity()){e.target.reportValidity();return}state[k]=Number(e.target.value);save();render()};
 document.querySelectorAll('[data-process]').forEach(el=>el.onchange=()=>{const o=current(),key=o.id+':'+el.dataset.process;state.completed=state.completed.filter(x=>x!==key);if(el.checked)state.completed.push(key);const s=schedule(),total=s.reduce((a,p)=>a+p.hours,0),done=s.filter(p=>state.completed.includes(o.id+':'+p.index)).reduce((a,p)=>a+p.hours,0);o.progress=Math.round(done/total*100);o.status=o.progress===100?'待回款':o.progress?'生产中':'待排产';log('更新 '+o.id+' 工序 '+PROCESS[Number(el.dataset.process)][0]);render()});
 if($('#confirm-export'))$('#confirm-export').onchange=e=>{$('#finance-export').disabled=!e.target.checked};
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.action;
 if(action==='new')orderForm();
 else if(action==='menu'){$('.sidebar').classList.add('open');$('.mobile-shade').classList.add('visible')}
 else if(action==='closeNav'){$('.sidebar').classList.remove('open');$('.mobile-shade').classList.remove('visible')}
 else if(action==='export')exportReport();
 else if(action==='financeExport'){if($('#confirm-export')?.checked)exportReport(true)}
 else if(action==='exportOrders'){download('匠融未来-订单清单.csv',csv([['订单编号','订单名称','客户','数量','单价','金额','预付款比例','交期天数','状态','进度'],...state.orders.map(o=>[o.id,o.name,o.customer,o.qty,o.price,o.qty*o.price,o.deposit,o.due,o.status,o.progress])]),'text/csv;charset=utf-8');log('导出订单清单');toast('订单清单已导出')}
 else if(action==='exportCash'){const f=flow();download(current().id+'-现金流.csv',csv([['情景',SCENARIOS.find(x=>x[0]===state.scenario)[1]],['期初现金',state.opening,'安全阈值',state.safety],['周期','期初现金','预计流入','预计流出','期末现金','安全阈值补足'],...f.rows.map(r=>['第'+r.week+'周',r.start,r.income,r.expense,r.balance,Math.max(0,state.safety-r.balance)])]),'text/csv;charset=utf-8');log('导出 '+current().id+' 现金流测算');toast('现金流明细已导出')}
 else if(action==='applyPlan'){save();log('保存拼贴人员 '+state.workers+' 人的排程方案');toast('排程方案已保存');}
 else if(action==='notifications'){modal('经营提醒',risks());$('#modal').querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>{$('#modal').close();go(el.dataset.go)})}
 else if(action==='about')modal('关于演示空间','<p>本系统根据《匠融未来》报告制作，使用芦苇画案例与明确标注的演示参数。</p><div class="notice">订单、排程和操作记录仅保存在当前浏览器，不构成真实银行业务。未接入账号登录、云端数据库、OCR 或大模型识别服务。</div><p class="muted">首次示例含 3 笔订单。实际使用前需校准工时、接入业务数据库，并完成银行接口授权。</p>');
 else if(action==='template')modal('芦苇画 · 工序模板',`<p class="muted" style="margin-bottom:15px">以下工时为原型演示假设，不是行业标准。</p><div class="table-wrap"><table><thead><tr><th>工序</th><th>单件工时</th><th>说明</th></tr></thead><tbody>${PROCESS.map(([name,hours,d])=>`<tr><td>${name}</td><td>${hours} 小时</td><td>${d}</td></tr>`).join('')}</tbody></table></div><div class="notice">工序按表内顺序执行。熟练人员默认每日 6 小时有效工时，拼贴可增加人数。不同规格应在试点后建立独立模板。</div>`);
 });
}
render();
